093824f00cc84d5650887b89fbd89ed6cae1e14b57ca2b141e6','55a0c65d3cfd52a211619ce79b73d103e611945264808be116be68dc46cd21a2',0,'2026-08-30 16:56:48.970'),('6c7e7b822deb476db4e6f59ef2aa0ecf',729,'3bbadcdb357a4f658691b3425d204a7e','4fd77addb4294dc3af11cc4285eff90b',NULL,'# 有机地标农场手册有机地标铜陵集团有限公司\n## “含铁冠军”——黑木耳\n食用黑木耳的记载。\n\n### 多糖\n\n- 黑木耳多糖是黑木耳的主要活性成分。具有抗凝血、抗血栓、降血脂、抗氧化等作用\n\n### 胶原蛋白\n\n### 黑色素\n\n### 微量元素\n\n- 世界卫生组织确认的人体必需微量元素有14种。黑木耳富含铁、锌、铜、锰等微量元素\n\n### 多酚类\n\n- 黑木耳中含有1.1%\\~1.3%的多酚。',1,221,0,'1955a86da154d421ebc814436dbbeebfb81694ad3acfe90d50ad9a1031f4d05d','1419f7df90edd68d7739380601a1992464f269319f0948fc652a7a047eb0cb01',0,'2026-08-29 20:44:58.349'),('6cadbc6626044b0db0d277e2b65b3053',1198,'3c0a80dc54fa4f119aa4b991247a80f6','46f595e392cd489a9a557fa17c96be3d',NULL,'# 检测报告\n## Beijing Century Kehuan Ecological Agriculture Institute 检测报告(Testing Report)\n氟氰菊酯和高效氯氟氰菊酯）</td><td rowspan=1 colspan=1>GB/T 5009.146-2008（2)</td><td rowspan=1 colspan=1>未检出(检出限：0.8)</td><td rowspan=1 colspan=1>μg/kg</td></tr><tr><td rowspan=1 colspan=1>3</td><td rowspan=1 colspan=1>氯氰菊酯（氯氰菊酯和高效氯氰菊酯）</td><td rowspan=1 colspan=1>GB 23200.8-2016</td><td rowspan=1 colspan=1>未检出(定量限：0.0376)</td><td rowspan=1 colspan=1>mg/kg</td></tr><tr><td rowspan=1 colspan=1>4</td><td rowspan=1 colspan=1>啶虫脒</td><td rowspan=1 colspan=1>GB/T 20769-2008</td><td rowspan=1 colspan=1>未检出(检出限：',1,300,0,'7ffd716bedd20aae9415fb969424cfda6e43774585bf0c97fc3b8c8ef2ee6d6d','6d92bd4f4c0aa4c36eaef4fff0f6cd7a5a869894abb2f30ed0914925715ea30c',0,'2026-08-30 16:54:56.668'),('6d7afde0512b4e7e9c619651278eaa14',999,'842fc51a01e8408d9485c1f839ae2543','06941c75d9da4ae2b5e3293414973d5c',NULL,'# 一、公司介绍\n## 1、有机产品\n（1）什么是“有机产品”?\n\n“有机产品”是指生产、加工、销售过程符合中国有机产品国家标准，获得有机产品认证证书，并加施中国有机产品认证标志的供人类消费、动物食用的产品。\n\n（2）什么是“有机产品认证”?\n\n有机产品认证是指认证机构按照《有机产品》国家标GB19630-\n\n2011和《有机产品认证管理办法》以及《有机产品认证实施规则》的规定对有机产品生产和加工过程进行评价的活动。在我国境内销售的有机产品均需经国家认监委批准的认证机构认证。',0,222,0,'2ba01342956b1711f21453acdd15eaf615d0b113bc3bc0d59ac0c2e2cf4f8e20','e92daca46358e96ac453cd6bb083780a95f4b830c9745a01e9cc19e215013076',0,'2026-08-29 21:04:35.314'),('70d882037d614d998fcad1c21c0f3a80',977,'842fc51a01e8408d9485c1f839ae2543','14348858664140aaa82da005a816312f',NULL,'# 一、公司介绍\n## 3、公司理念\n机标准，采用生态友好型种植方式，确保食用菌在无污染的环境中生长。同时，在种植环节依托自主研发的神农大脑智慧农业系统和现代化设备，实现精准灌溉、温湿度控制等（市面上多数采用传统种植，质量参差不一），为食用菌创造最佳生长条件，从而保证其口感鲜美、营养丰富）。',1,182,0,'df4426847981375bea7258b007585be9652afbe6a71ad5c4c67e45d12bd703fb','5e19041e0bdbab225b578f2fdd76fc2d88372d56b359d1abd5026376d28f1751',0,'2026-08-29 21:04:35.314'),('71a237253fe54d6882130cfed151756e',1298,'05041ccb31864c798c28cba80d196bea','db6646686ea2490db12cb88f049cdfb4',NULL,'# 检测报告\n## 北京世纪科环生态农业研究院Beijing Century Kehuan Ecological Agriculture Institute检测报告(Testing Report)\n呋虫胺）</td><td rowspan=2 colspan=1>GB/T 20769-2008</td><td rowspan=2 colspan=1>未检出(检出限：2.55)</td><td rowspan=2 colspan=1>μg/kg</td><td rowspan=2 colspan=1></td></tr><tr><td rowspan=1 colspan=1>5</td></tr><tr><td></td><td rowspan=2 colspan=1>溴氰菊酯</td><td rowspan=2 colspan=1>GB 23200.8-2016</td><td rowspan=2 colspan=1>未检出(定量限：0.0750)</td><td rowspan=2 colspan=1>mg/kg</td><td rowspan=2 colspan=1></td></tr><tr><td rowspan=1 colspan=1>6</td></tr><tr><td rowspan=1 colspan=1>7</td><td rowspan=1 colspan=1>多菌灵</td><td rowspan=1 colspan=1>GB/T 20769-2008</td',3,300,0,'75a3c65905b2c18938e059b566dc4e1ab2db908c2f3292b5c21d177bbae6d6ab','b12f3cddc5a8b74a6af8bea4ef10bb39390d17cf54fbf7e0bd2da0a75ccfa60f',0,'2026-08-30 16:56:59.660'),('71a8184311dd4b8b9f2b2041604d29af',1035,'aec61125b035410f864b18e6d39e1201','a2babe797fc941c3afcf99ba0f572864',NULL,'# 打造工厂化食用菌产业园区为目标\n## 数字化设施农业之二植物阳光智能工厂\n- 有机地标引进的是日本太阳光利用型植物工厂系统。工作人员只要在计算机上设定好关键数值，一切都会自动控制。当夏季棚内气温过高时，顶端两层遮阳网会自动打开，防止强光直接照射；高温高湿时还会打开风机换气。\n\n营养液输送管道系统也装有恒温装置，可维持蔬菜生长最适宜温度，十分适合蔬菜的吸收。一般土地种植蔬菜的生长周期在2～3月，但这里的蔬菜一般20天左右就能收割了。',0,274,0,'e8676e2d6b9f3c14d848d4d2deec0ccd2f6618b15156b0efb3a6a6c3840e0674','398e716d39cf3e203d8c36ec1efca816e2eaeac5f1e50a2cf3736f2ff257a464',0,'2026-08-29 21:05:00.593'),('74b9008ffc2744b5a10898f2343359a8',1029,'aec61125b035410f864b18e6d39e1201','0a3cec8cf37d4edba09bef0ba94e4a6c',NULL,'# 打造工厂化食用菌产业园区为目标\n## 在产业化模式方面\n通过“公司技术指导+基地种菌培育+农户种植”的农业产业化模式，建立年产7200万袋食用菌种植基地',0,88,0,'f1cce6e8e15b51b1e2ca03e2031db4fd46242fb5c98e2b3fb39ab3358b59aa4d','f1cce6e8e15b51b1e2ca03e2031db4fd46242fb5c98e2b3fb39ab3358b59aa4d',0,'2026-08-29 21:05:00.593'),('757e7bab18f4409aa894ab1c343b28fd',1044,'aec61125b035410f864b18e6d39e1201','c2aed2173b5840ce95b8b6972fc53729',NULL,'# 打造工厂化食用菌产业园区为目标\n## 一、标准化生产管理系统\n- 1.物料采购、生产种植\n- 2.采摘包装、物流销售\n- 3.任务分配、专家智库\n\n四、农产品交易系统农资数据\n\n- 1.建立B2B供应链系统\n- 2.接入第三方电商平台\n- 3.接入物流系统\n\n农产数据\n\n农户',0,142,0,'8277c267e49203b57872e8c52104d06c49ed8fae8c5df8cff5f7a5c56ebd053c','8277c267e49203b57872e8c52104d06c49ed8fae8c5df8cff5f7a5c56ebd053c',0,'2026-08-29 21:05:00.593'),('75bf1ca54f1044d0be175ccb6577a5d1',1062,'aec61125b035410f864b18e6d39e1201','b62b25810ed4451284ba7e4531192c5c',NULL,'# 打造工厂化食用菌产业园区为目标\n## 地润3号-盐碱地专用\n封闭盐碱，固化分解。增加土壤颗粒空隙，改善作物生长环境，提高自我屏蔽有害物质吸收、修复自然菌群及生态平衡的能力。',0,113,0,'0a26d4363253843116f4cd27fbd86fe77a0a11056b076d2584bb5610acab3739','0a26d4363253843116f4cd27fbd86fe77a0a11056b076d2584bb5610acab3739',0,'2026-08-29 21:05:00.593'),('75e249e99f094c3dafbd6c0398c33625',744,'3bbadcdb357a4f658691b3425d204a7e','33bfa28bf48b4916bcf5e9e45e4805ac',NULL,'# 有机地标农场手册有机地标铜陵集团有限公司\n## 八款珍馐，集于一盒——山珍礼盒\n中含有多种氨基酸，尤以赖氨酸和亮氨酸的含量最为丰富。\n\n### 鹿茸菇\n\n含有高蛋白质和多种氨基酸、维生素B1、B2、C和PP，具有很高的营养价值和特殊的药用效果。经烹调后，脆松适度，味道可口，如配上猪、鸡肉共炒，则食味更加鲜美。\n\n### 松茸菌\n\n松茸被称为“蘑菇之王”。其菇体肥大，肉质细嫩，是一种美味可口，并具有一定药用价值的名贵食用菌。',1,277,0,'10bdc86010bb5a31875988cb6cdc2b5740af690da2f49e650ee99b23eee94d82','743f9a232595a18e60f977c5e7a00e8684395a5a915f83fbfab16ea4e94524db',0,'2026-08-29 20:44:58.349'),('765cd51a7ebf432d80779bdc28b5809a',973,'842fc51a01e8408d9485c1f839ae2543','2e4c0ea1a0d242078e60ee341e9db316',NULL,'# 一、公司介绍\n## 2、公司概括\n有机地标（桂林）生态农业有限公司成立于2024 年11月，扎根桂林山水间的生态禀赋，以“用科技赋能生态农业，以产业振兴乡村”为使命，致力于打造集“科研创新、智能生产、品牌营销、价值延伸”于一体的现代化生态农业标杆企业，让优质菌菇产业成为激活乡村经济的新引擎。公司现阶段聚焦新媒体运营核心板块，以“创新内容+数字营销”为抓手，构建品牌与消费者的深度连接。',0,236,0,'8590eb92a619373382d262cc1f1b7e98bf092f4a9ab6d9662917e8bface4d714','a63ad5dc6f11f9f0210e242e186cfeea99f17332d8eeabbad85253270a587618',0,'2026-08-29 21:04:35.314'),('767542d8c8b344b7b8e2479288eb01b8',741,'3bbadcdb357a4f658691b3425d204a7e','8de77c3fdd994912ab051ce4f3867ee4',NULL,'# 有机地标农场手册有机地标铜陵集团有限公司\n## “菌中黄金”——松茸菌\n松茸被称为“菌中黄金”。其菇体肥大，肉质细嫩，是一种美味可口，并具有一定药用价值的名贵食用菌。 [10]由于经济价值很高被掠夺式开发，许多地区野生资源量急剧下降。2021年，被列入国家二级重点保护野生物种行列。 [3]松茸在食品产业中，由于其香味独特浓郁、菌肉肥厚、鲜嫩爽滑及营养成分高等特点，具有极高地位。',0,241,0,'302687e57a013fdea8c0d27b45c07a130cab9acee99f04b585c8ef34d0118594','302687e57a013fdea8c0d27b45c07a130cab9acee99f04b585c8ef34d0118594',0,'2026-08-29 20:44:58.349'),('769b4e7dcbde4a9899c1d22ba2e12235',1205,'4616880e16f04163870d4a17a17fba74','ca2725405b664859b5fc5530388cb425',NULL,'# 检测报告\n## 声明\nwill refund the retest fee. Overdue is deemed to be without objection.\n\n- 3、不可重复或不能进行复测的实验，不进行复测。\n\nExperiments that cannot be repeated or cannot be tested shall not be carried out again.\n\n- 4、委托单位提供样品时应对样品的代表性和资料的真实性负责。\n\nThe principal is responsible for the representativeness of the samples and the authenticity of the data when providing samples.\n\n- 5、本报告仅对所测样品负责，报告数据仅反映对所测样品的评价，对于报告及所载内容的使用、使用所产生的直接或间接损失及一切法律后果，本单位不承担任何经济和法律责任。\n\nThis report is only responsible for the provided sample.The test results only represent the evaluation of the tested sample. BCT will not be responsible for any economical or legal liability generated from direct or indirect usage of the test report.\n\n- 6、本单位有权在完成报告后处理样品。',1,278,0,'610d01d369411615b4116669ab1f9bcdd00763b446c1f7237df65e4ae88b4c86','09f44c67d2f6c56ce988436ef8a1641e8dfc8e9aad5441a8565f856ca87de341',0,'2026-08-30 16:55:32.794'),('76ad6fe4b2a54732877967fc5a853c2f',1047,'aec61125b035410f864b18e6d39e1201','3c130b7cb93f47748ca7eac1f031acc0',NULL,'# 打造工厂化食用菌产业园区为目标\n## 六、项目合作交易系统\n特色创新服务运营机制建设\n\n- 1. 招商引资\n\n- 2. 金融监管\n\n- 3.接入“有机地标”\n\n农商数据服务数据创新运营机制创新投入机制创新可持续发展机制',0,114,0,'b87369d60ff199a625844a741638eb90c5cfd6c239180c7256be3ac1e3eefc4a','b87369d60ff199a62