  PRIMARY KEY (`file_id`),
  CONSTRAINT `fk_staging_file` FOREIGN KEY (`file_id`) REFERENCES `metadata` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='发布暂存表';
