--
-- Table structure for table `rag_parent_block`
--

DROP TABLE IF EXISTS `rag_parent_block`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rag_parent_block` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '数据库自增主键',
  `tenant_id` varchar(64) NOT NULL COMMENT '租户 ID',
  `kb_id` varchar(64) NOT NULL COMMENT '知识库 ID',
  `parent_id` varchar(128) NOT NULL COMMENT '父块业务 ID，Milvus 子块 metadata 中的 parent_id',
  `title` varchar(512) DEFAULT NULL COMMENT '父块标题',
  `content` mediumtext NOT NULL COMMENT '父块正文，作为 LLM 上下文的权威内容',
  `summary` text COMMENT '可选摘要，用于展示或粗排',
  `source_type` varchar(32) NOT NULL DEFAULT 'document' COMMENT '来源类型：document / url / manual / database 等',
  `source_id` varchar(255) DEFAULT NULL COMMENT '来源系统里的原始文档 ID',
  `source_uri` varchar(1024) DEFAULT NULL COMMENT '来源路径、URL 或对象存储地址',
  `category` varchar(128) DEFAULT NULL COMMENT '业务分类',
  `tags` json DEFAULT NULL COMMENT '扩展标签',
  `status` varchar(32) NOT NULL DEFAULT 'active' COMMENT '状态：draft / active / disabled / deleted',
  `visibility` varchar(32) NOT NULL DEFAULT 'private' COMMENT '可见性：private / tenant / public 等',
  `doc_version` bigint unsigned NOT NULL DEFAULT '1' COMMENT '内容版本号，每次更新递增',
  `content_sha256` char(64) NOT NULL COMMENT '父块内容哈希，用于一致性校验和缓存失效',
  `content_chars` int unsigned NOT NULL DEFAULT '0' COMMENT '正文字符数',
  `effective_at` datetime(3) DEFAULT NULL COMMENT '生效时间',
  `expired_at` datetime(3) DEFAULT NULL COMMENT '过期时间',
  `published_at` datetime(3) DEFAULT NULL COMMENT '发布时间',
  `created_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) DEFAULT NULL COMMENT '最后更新人',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_kb_parent` (`tenant_id`,`kb_id`,`parent_id`),
  KEY `idx_tenant_kb_status` (`tenant_id`,`kb_id`,`status`),
  KEY `idx_source` (`source_type`,`source_id`),
  KEY `idx_updated_at` (`updated_at`),
  CONSTRAINT `chk_rag_parent_block_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'active',_utf8mb4'disabled',_utf8mb4'deleted')))
) ENGINE=InnoDB AUTO_INCREMENT=506 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='RAG 父块权威内容表';
/*!40101 SET character_set_client = @saved_cs_client */;

