INSERT INTO `rag_parent_block` VALUES (292,'Influencer','Influencer_knowlege','8fbf2cb508044e7b935d374af315ea0a','- **公司介绍**','- **公司介绍**\n\n**1、集团概括**\n有机地标(铜陵)控股集团有限公司坐落于农业大省安徽省铜陵市（目前集团准备搬迁至江苏省南京市，并更名为有机地标（江苏）控股集团），是一家从事育繁推一体化农业体系建设，以现代种业、农产品加工业、市场流通业及其他产业等“3+N”产业为重点，集合农业种植、科技研发、物联网及区块链技术服务、销售等服务的大型农业全产业链集团公司。在安徽拥有两大农业基地，占地超2000亩。在现代设施农业建设与园区运营管理方面拥有丰富的实践经验，实现了现代智慧农业产业园区全产业链的有效闭合，荣获“安徽省数字农业工厂”“先进单位”、“铜陵市科普示范基地”铜陵市首个“安徽省节水教育实践基地”等荣誉。\n\n有机地标集团隶属于中应投资建设集团，位于江苏省南京市江宁区麒麟科创园，实缴注册资金30,000万元。在业务种类的拓展上，集团采取“稳扎稳打、求实务实”的发展战略。经营范围涵盖城市建设投资、产业投资、大宗贸易等，城市建设投资主要包括城市更新、连片开发、政府项目代建、安置房投资建设等；产业投资涉及应急产业发展、新能源产业投资、储能电源投资、生物材料产业投资、职业院校、氢能源产业、旅游及康养产业、乡村振兴产业等；大宗商品贸易主要销售农产品、粮油、化工产品、建材、煤炭等。','- **公司介绍**\n\n**1、集团概括**\n有机地标(铜陵)控股集团有限公司坐落于农业大省安徽省铜陵市（目前集团准备搬迁至江苏省南京市，并更名为有机地标（江苏）控股集团），是一家从事育繁推一体化农业体系建设，以现代种业、农产品加工业、市场流通业及其他产业等“3+N”产业为重点，集合农业种植、科技研发、物联网及区块链技术服务、销售等服务的大型农业全产业链集团公司。在安徽拥有两大农业基地，占地超2000亩。在现代设施农业建设与园区运营管理方面拥有丰富的实践经验，实现了现代智慧农业产业园区全产业链的有效闭合，荣获“安徽省数字农业工厂”“先进单位”、“铜陵市科普示范基地”铜陵市首个“安徽省节水教育实践基地”等荣誉。\n\n有机地标集团隶属于中应投资建设集团，位于江苏省南京市江宁区麒麟科创园，实缴注册资金30,000万元。在业务种类的拓展上，集团采取“稳扎稳打、求实务实”的发展战略。经营范围涵盖城市建设投资、产业投资、大宗贸易等，城市建设投资主要包括城市更新、连片开发、政府项目代建、安置房投资建设等；产业投资涉及应急产业发展、新能源产业投资、储能电源投资、生物材料产业投资、职业院校、氢能源产业、旅游及康养产业、乡村振兴产业等；大宗商品贸易主要销售农产品、粮油、化工产品、建材、煤炭等。','document','528f5b96d0434673b10c97847ff1f238','D:\\my_project\\file pipeline channel\\uploads\\694bb22c5f621b3b9d4addda61f47d8c05d31d9f5d6496cd9b13eddb6ca8c60c.docx','公司','{\"product_id\": \"1\"}','deleted','tenant',1,'deac1a85a98fcad537ebfd4a231edf981b70f16d34d111fca49c9f8fa3a9761e',544,NULL,NULL,'2026-08-28 15:15:51.749','pipeline','pipeline','2026-08-28 15:15:51.750','2026-08-29 21:01:47.393'),(293,'Influencer','Influencer_knowlege','03df193dd3f84d6d97bb1001015b9257','**2、公司概括**','**2、公司概括**\n有机地标（桂林）生态农业有限公司成立于2024年11月，扎根桂林山水间的生态禀赋，以“用科技赋能生态农业，以产业振兴乡村”为使命，致力于打造集“科研创新、智能生产、品牌营销、价值延伸”于一体的现代化生态农业标杆企业，让优质菌菇产业成为激活乡村经济的新引擎。\n\n公司现阶段聚焦新媒体运营核心板块，以“创新内容+数字营销”为抓手，构建品牌与消费者的深度连接。并将分阶段推进全产业链布局：成立食用菌种业研究院深耕核心技术；规划建设全智能菌种工厂、全智能菌棒工厂，夯实产业基础；同步落地多元化菌菇食品深加工生产线，延伸价值链条。\n\n未来，有机地标（桂林）将以“新媒体品牌力+全产业链硬实力”双轮驱动，不仅让生态菌菇走进千家万户的餐桌，更通过“企业+合作社+农户”模式，带动本地菌农标准化种植、规模化增收，真正实现“一片菌菇富一方百姓”，为中国生态农业高质量发展与乡村全面振兴贡献“有机地标方案”。','**2、公司概括**\n有机地标（桂林）生态农业有限公司成立于2024年11月，扎根桂林山水间的生态禀赋，以“用科技赋能生态农业，以产业振兴乡村”为使命，致力于打造集“科研创新、智能生产、品牌营销、价值延伸”于一体的现代化生态农业标杆企业，让优质菌菇产业成为激活乡村经济的新引擎。\n\n公司现阶段聚焦新媒体运营核心板块，以“创新内容+数字营销”为抓手，构建品牌与消费者的深度连接。并将分阶段推进全产业链布局：成立食用菌种业研究院深耕核心技术；规划建设全智能菌种工厂、全智能菌棒工厂，夯实产业基础；同步落地多元化菌菇食品深加工生产线，延伸价值链条。\n\n未来，有机地标（桂林）将以“新媒体品牌力+全产业链硬实力”双轮驱动，不仅让生态菌菇走进千家万户的餐桌，更通过“企业+合作社+农户”模式，带动本地菌农标准化种植、规模化增收，真正实现“一片菌菇富一方百姓”，为中国生态农业高质量发展与乡村全面振兴贡献“有机地标方案”。','document','528f5b96d0434673b10c97847ff1f238','D:\\my_project\\file pipeline channel\\uploads\\694bb22c5f621b3b9d4addda61f47d8c05d31d9f5d6496cd9b13eddb6ca8c60c.docx','公司','{\"product_id\": \"1\"}','deleted','tenant',1,'0c7e5cca38743bdd05ed368914a340fc1ffbf373ce19882241450075644939b7',405,NULL,NULL,'2026-08-28 15:15:51.749','pipeline','pipeline','2026-08-28 15:15:51.754','2026-08-29 21:01:47.393'),(294,'Influencer','Influencer_knowlege','4f26306651004cdfa8875561ee5dd55b','**3、公司理念**','**3、公司理念**\n有机地标一直以来专注于食用菌产品的精品打造，在食品安全领域精耕细作。我们深知食用菌作为广受消费者喜爱的健康食材，其质量安全至关重要，始终秉持着“品质至上，安全先行” 的理念，从源头把控食用菌的品质，**自主研发选取优质、高产且抗逆性强的菌种**（市面上种植基地多数为购买菌种进行种植），为食用菌的优良品质奠定坚实基础。在种植过程中，严格**遵循有机标准，采用生态友好型种植方式**，确保食用菌在无污染的环境中生长。同时，在种植环节依托**自主研发的神农大脑智慧农业系统和现代化设备**，实现精准灌溉、温湿度控制等（市面上多数采用传统种植，质量参差不一），为食用菌创造最佳生长条件，从而保证其口感鲜美、营养丰富）。\n\n**4、公司信念**\n（1）使命：一粒菌种改变世界；\n\n（2）愿景：成为世界级食用菌产业链领导者；\n\n（3）价值观：务实进取、努力奋斗、合作共赢、勇于创新，坚持乡村振兴三农发展为奋斗目标。','**3、公司理念**\n有机地标一直以来专注于食用菌产品的精品打造，在食品安全领域精耕细作。我们深知食用菌作为广受消费者喜爱的健康食材，其质量安全至关重要，始终秉持着“品质至上，安全先行” 的理念，从源头把控食用菌的品质，**自主研发选取优质、高产且抗逆性强的菌种**（市面上种植基地多数为购买菌种进行种植），为食用菌的优良品质奠定坚实基础。在种植过程中，严格**遵循有机标准，采用生态友好型种植方式**，确保食用菌在无污染的环境中生长。同时，在种植环节依托**自主研发的神农大脑智慧农业系统和现代化设备**，实现精准灌溉、温湿度控制等（市面上多数采用传统种植，质量参差不一），为食用菌创造最佳生长条件，从而保证其口感鲜美、营养丰富）。\n\n**4、公司信念**\n（1）使命：一粒菌种改变世界；\n\n（2）愿景：成为世界级食用菌产业链领导者；\n\n（3）价值观：务实进取、努力奋斗、合作共赢、勇于创新，坚持乡村振兴三农发展为奋斗目标。','document','528f5b96d0434673b10c97847ff1f238','D:\\my_project\\file pipeline channel\\uploads\\694bb22c5f621b3b9d4addda61f47d8c05d31d9f5d6496cd9b13eddb6ca8c60c.docx','公司','{\"product_id\": \"1\"}','deleted','tenant',1,'686fe3823c5652308929e9ca4aa8256d9d4e4e4ff2dc267f2450033696ce1e72',413,NULL,NULL,'2026-08-28 15:15:51.749','pipeline','pipeline','2026-08-28 15:15:51.755','2026-08-29 21:01:47.393'),(295,'Influencer','Influencer_knowlege','5316b3ab9dd74f6ea1a69afc3ff5274a','**5、公司产业链**','**5、公司产业链**\n公司以“科技驱动、全链协同、价值倍增”为原则，构建“研（种业自研）-产（生态种植）-加（精深加工）-销（品牌赋能）”四位一体的食用菌全产业链生态，深度融合桂林生态禀赋与现代农业技术，既保障产品“从菌棒到餐桌”的品质可控，又通过产业链延伸激活乡村经济，让每一朵菌菇都成为“科技赋能+产业振兴”的生动注脚。\n\n（1）研：掌握产业“芯片”，守护本土种质资源​\n\n公司全产业链的“技术大脑”，聚焦“本土菌种保护+创新育种+技术输出”，解决传统菌菇种植“菌种退化、抗逆性差、产量不稳定”痛点。\n\n食用菌研究院：联合广西农科院微生物所、中科院植物研究所、广西特色作物研究院、广西师范大学生科院等机构，系统收集广西地区菌菇种质资源，引入分子标记辅助育种、基因编辑等技术，定向选育“高产（较传统菌种增产20%+）、抗病（杂菌感染率降低30%）、优质（氨基酸/多糖含量提升15%）”的本土化菌种。\n\n（2）产：标准化生产“新基建”，降本增效保品质​\n\n公司全产业链的“品质中枢”，通过智能化设备替代传统人工操作，实现菌种扩繁、菌棒生产的全程可控、全程追溯，为后续加工与销售提供“稳定、安全、低成本”的原料保障。\n\n1）全智能菌种工厂\n\n采用“物联网+AI环境调控”系统，实时监控菌种扩繁环节的温湿度（±0.5℃精度）、光照强度、CO₂浓度（自动换气），搭配自动化接种线（减少人为污染），使菌种成活率提升至98%以上（传统人工接种约85%）；\n\n产能规划：一期建成800㎡智能车间，年扩繁菌种50万支；\n\n2）全智能菌棒工厂\n\n集成“自动化配料（秸秆/木屑/罗汉果渣/蔗渣等科学配比）→ 高压灭菌（120℃持续10小时灭杂菌）→ 无菌接种（机械臂精准植入菌种）→ 恒温培养（25℃±1℃发菌）”全流程，搭配无人传输带转运菌棒，避免人工接触污染；\n\n产能规划：一期建成16000㎡智能生产车间，日生产菌棒10万包，年产3500万包，可满足2500亩菌棒种植需求；\n\n3）生态种植\n\n公司在桂林市选取无污染、生态环境好、水源充裕的乡村，通过采用“公司+合作社+农户”模式，实现乡村振兴连接。以“成本价+技术指导”向本地合作社/农户供应菌棒，签订“保底收购协议”（鲜菇收购价高于市场价5%-10%），带动农户“零技术门槛”参与种植，预计单户年均增收3-5万元。','**5、公司产业链**\n公司以“科技驱动、全链协同、价值倍增”为原则，构建“研（种业自研）-产（生态种植）-加（精深加工）-销（品牌赋能）”四位一体的食用菌全产业链生态，深度融合桂林生态禀赋与现代农业技术，既保障产品“从菌棒到餐桌”的品质可控，又通过产业链延伸激活乡村经济，让每一朵菌菇都成为“科技赋能+产业振兴”的生动注脚。\n\n（1）研：掌握产业“芯片”，守护本土种质资源​\n\n公司全产业链的“技术大脑”，聚焦“本土菌种保护+创新育种+技术输出”，解决传统菌菇种植“菌种退化、抗逆性差、产量不稳定”痛点。\n\n食用菌研究院：联合广西农科院微生物所、中科院植物研究所、广西特色作物研究院、广西师范大学生科院等机构，系统收集广西地区菌菇种质资源，引入分子标记辅助育种、基因编辑等技术，定向选育“高产（较传统菌种增产20%+）、抗病（杂菌感染率降低30%）、优质（氨基酸/多糖含量提升15%）”的本土化菌种。\n\n（2）产：标准化生产“新基建”，降本增效保品质​\n\n公司全产业链的“品质中枢”，通过智能化设备替代传统人工操作，实现菌种扩繁、菌棒生产的全程可控、全程追溯，为后续加工与销售提供“稳定、安全、低成本”的原料保障。\n\n1）全智能菌种工厂\n\n采用“物联网+AI环境调控”系统，实时监控菌种扩繁环节的温湿度（±0.5℃精度）、光照强度、CO₂浓度（自动换气），搭配自动化接种线（减少人为污染），使菌种成活率提升至98%以上（传统人工接种约85%）；\n\n产能规划：一期建成800㎡智能车间，年扩繁菌种50万支；\n\n2）全智能菌棒工厂\n\n集成“自动化配料（秸秆/木屑/罗汉果渣/蔗渣等科学配比）→ 高压灭菌（120℃持续10小时灭杂菌）→ 无菌接种（机械臂精准植入菌种）→ 恒温培养（25℃±1℃发菌）”全流程，搭配无人传输带转运菌棒，避免人工接触污染；\n\n产能规划：一期建成16000㎡智能生产车间，日生','document','528f5b96d0434673b10c97847ff1f238','D:\\my_project\\file pipeline channel\\uploads\\694bb22c5f621b3b9d4addda61f47d8c05d31d9f5d6496cd9b13eddb6ca8c60c.docx','公司','{\"product_id\": \"1\"}','deleted','tenant',1,'8db2c344cbb31a6449c7ed7186484b4ce561dc838f9a5304b152ea9e979bee6e',979,NULL,NULL,'2026-08-28 15:15:51.749','pipeline','pipeline','2026-08-28 15:15:51.756','2026-08-29 21:01:47.393'),(296,'Influencer','Influencer_knowlege','0fc180d01bfe4557a86493995a3f5065','**5、公司产业链**','**5、公司产业链**\n（3）加：多元化菌菇食品深加工生产线——延伸价值链条，覆盖全场景消费​\n\n通过成立食用菌食品开发所，采用“研发先行、工厂跟进”模式，先通过食用菌食品开发所洞察需求、定向研发，再通过食用菌深加工工厂实现规模化生产，确保产品“市场适配性+技术壁垒+品质稳定性”三者兼备。\n\n1）食用菌食品开发所\n\n公司以“市场需求为导向、技术突破为支撑、场景适配为目标”，专注食用菌深加工产品的“从0到1”研发，解决传统加工“产品同质化、附加值低、场景单一”痛点。\n\n从“卖菌菇”到“卖价值”的关键跃升，通过深加工将初级农产品转化为高附加值食品，同时消化加工边角料（公司现有产品如羊肚菌菌渣加工成羊肚菌辣椒酱，大片黑木耳切丝加工成即食木耳丝）实现循环经济。\n\n**注**\n：公司新媒体团队，需实时收集用户反馈（如C端对于市场食品“低钠健康”、“办公室零食”等需求）。\n\n2）食用菌深加工工厂\n\n以“智能化生产+绿色制造+柔性适配”为原则，将开发所输出的“产品方案”转化为规模化商品，保障品质稳定、成本可控、产能弹性。\n\n产能规划：一期建成10000㎡标准生产车间，待产品开发后在构建生产线。\n\n（4）销：新媒体品牌+C端——让“桂林菌菇”走向全国餐桌​','**5、公司产业链**\n（3）加：多元化菌菇食品深加工生产线——延伸价值链条，覆盖全场景消费​\n\n通过成立食用菌食品开发所，采用“研发先行、工厂跟进”模式，先通过食用菌食品开发所洞察需求、定向研发，再通过食用菌深加工工厂实现规模化生产，确保产品“市场适配性+技术壁垒+品质稳定性”三者兼备。\n\n1）食用菌食品开发所\n\n公司以“市场需求为导向、技术突破为支撑、场景适配为目标”，专注食用菌深加工产品的“从0到1”研发，解决传统加工“产品同质化、附加值低、场景单一”痛点。\n\n从“卖菌菇”到“卖价值”的关键跃升，通过深加工将初级农产品转化为高附加值食品，同时消化加工边角料（公司现有产品如羊肚菌菌渣加工成羊肚菌辣椒酱，大片黑木耳切丝加工成即食木耳丝）实现循环经济。\n\n**注**\n：公司新媒体团队，需实时收集用户反馈（如C端对于市场食品“低钠健康”、“办公室零食”等需求）。\n\n2）食用菌深加工工厂\n\n以“智能化生产+绿色制造+柔性适配”为原则，将开发所输出的“产品方案”转化为规模化商品，保障品质稳定、成本可控、产能弹性。\n\n产能规划：一期建成10000㎡标准生产车间，待产品开发后在构建生产线。\n\n（4）销：新媒体品牌+C端——让“桂林菌菇”走向全国餐桌​','document','528f5b96d0434673b10c97847ff1f238','D:\\my_project\\file pipeline channel\\uploads\\694bb22c5f621b3b9d4addda61f47d8c05d31d9f5d6496cd9b13eddb6ca8c60c.docx','公司','{\"product_id\": \"1\"}','deleted','tenant',1,'b99c03e6ce5db656b4e87d31210c9b3fb8de70b36e1b4cc8436e5d5cfbc86910',528,NULL,NULL,'2026-08-28 15:15:51.749','pipeline','pipeline','2026-08-28 15:15:51.757','2026-08-29 21:01:47.393'),(297,'Influencer','Influencer_knowlege','a929a521d9d344e987b96c9ffd22ed1e','**6、公司客户**','**6、公司客户**\n公司产品供应优质B端客户：黑木耳作为国家战略储备物资、签约香港大昌行保供香港食用菌物资、签约南京农垦拾味堂作为供应江苏政府食堂食材；国际顶级酒店香格里拉酒店、美高梅酒店；国内大型餐饮店海底捞、小菜园、老乡鸡等；线上平台：叮咚买菜；供港澳食用菌基地和出口欧盟26国。\n\n**7、公司管理体系**\n公司管理认证体系完善，目前拥有：ISO22000（食品安全管理体系）、ISO9000（质量管理体系）、ISO14000（环境管理体系）。','**6、公司客户**\n公司产品供应优质B端客户：黑木耳作为国家战略储备物资、签约香港大昌行保供香港食用菌物资、签约南京农垦拾味堂作为供应江苏政府食堂食材；国际顶级酒店香格里拉酒店、美高梅酒店；国内大型餐饮店海底捞、小菜园、老乡鸡等；线上平台：叮咚买菜；供港澳食用菌基地和出口欧盟26国。\n\n**7、公司管理体系**\n公司管理认证体系完善，目前拥有：ISO22000（食品安全管理体系）、ISO9000（质量管理体系）、ISO14000（环境管理体系）。','document','528f5b96d0434673b10c97847ff1f238','D:\\my_project\\file pipeline channel\\uploads\\694bb22c5f621b3b9d4addda61f47d8c05d31d9f5d6496cd9b13eddb6ca8c60c.docx','公司','{\"product_id\": \"1\"}','deleted','tenant',1,'82aa094b81bf1648ce4c1345d8c6f63ea19dc9933b47940a5d00f2ab8365661f',226,NULL,NULL,'2026-08-28 15:15:51.749','pipeline','pipeline','2026-08-28 15:15:51.759','2026-08-29 21:01:47.393'),(298,'Influencer','Influencer_knowlege','ceceafdcb8854b9d9b927af90b64aef8','**8、公司荣誉**','**8、公司荣誉**\n**（1）国内最大规模有机产品认证**\n\n项目基地产品获得有机产品认证，认证的食用菌产量为3519吨，为目前国内认证规模最大的有机食用菌基地。\n\n![](/media/images/a55e3441d44d82a1ddc3b22538662b1b2ab3c81c4e98e029126c58fd96603323.jpg)\n\n![](/media/images/c68c3f18be59d29404af28d0cd78d23e5574fc5ba6dc01b9cdf878a7613bc0c2.jpg)\n\n（2）乡村振兴标杆项目\n\n![](/media/images/79307e198d16bad858c8dd80a21d63d1c1428bb971a31010d4e58b9a16206dc4.jpg)\n\n**（3）入选央视“寻百强 看中国”栏目**\n\n有机地标食用菌基地成功入选了全国100座市县区县域经济高质量发展的代表。\n\n![](/media/images/668497bf403461999d55ce7212966a0dda88c098b7261acb68c8a97c444ffd3f.jpg)\n\n**（4）打造枞阳地标产品**\n\n有机地标食用菌基地生产的羊肚菌已经打造成为枞阳县的地理标志产品，为当地凸显着区域特色,打造地方、区域品牌积累文化属性。\n\n![](/media/images/e63790cf004ade7ab7f9ef61cf15e87fe7ffb6239fb307eff7e0b600bb442d0d.jpg)\n\n**（5）长三角数字农业优秀案例**\n\n有机地标基地凭借在数字化转型方面的创新能力和实践成果，荣获了2023年智慧长三角数字化转型优秀案例二等奖。\n\n![](/media/images/d7e4334eed5856e6c240e6104d7de93c657cb8c4b466a3d7779ca5bb1d44c6d2.jpg)\n\n**（6）供港澳食品种植基地**\n\n有机地标食用菌基地其高品质的产品成为保障港澳“菜篮子”的安全稳定的种植基地。\n\n![](/media/images/d18beb5676ab8c874c67b805389b24ea28eef8b5908fbbb9fcea9d9ed4c6faa8.jpg)\n\n（7）首届安徽省新农人创业创新大赛一等奖\n\n本次大赛以“徽风皖韵大农业 逐梦江淮新农人”为主题，围绕组织振兴、产业振兴、人才振兴、文化振兴、生态振兴等选题，包含农业新技术、农业资源高效利用、农产品电子商务、农业金融保险、农业特色小镇等内容，覆盖范围广，针对性强。有机地标从众多参赛项目中脱颖而出，斩获大赛一等奖。\n\n![](/media/images/01f5ecc1bfca26d0342a39ed5530fd7d212c770ecfcffa0a47acb63fb400c18c.jpg)\n\n9、**领导关怀**\n\n![](/media/images/9347e74cd78efb6680b8bf31486a68883793769d2fcdfaf96cef2413984c854b.jpg)\n\n**全国人大常委会副委员长吉炳轩率队检查乡村振兴工作**\n\n![](/media/images/90894683581b6bcfc5b6aa214c5a4f878b5f2fcc88efa92f5ed61e90340cce83.jpg)\n\n**中国农业国际合作促进会会长翟虎渠视察园区**\n\n![](/media/images/8a426b0593af26e6924b9f15a616d7f1dcbbc7d4e83618eca3177963026a3394.jpg)\n\n**中国乡村振兴发展中心副主任罗朝立到园区调研**\n\n- 产品介绍','**8、公司荣誉**\n**（1）国内最大规模有机产品认证**\n\n项目基地产品获得有机产品认证，认证的食用菌产量为3519吨，为目前国内认证规模最大的有机食用菌基地。\n\n![](/media/images/a55e3441d44d82a1ddc3b22538662b1b2ab3c81c4e98e029126c58fd96603323.jpg)\n\n![](/media/images/c68c3f18be59d29404af28d0cd78d23e5574fc5ba6dc01b9cdf878a7613bc0c2.jpg)\n\n（2）乡村振兴标杆项目\n\n![](/media/images/79307e198d16bad858c8dd80a21d63d1c1428bb971a31010d4e58b9a16206dc4.jpg)\n\n**（3）入选央视“寻百强 看中国”栏目**\n\n有机地标食用菌基地成功入选了全国100座市县区县域经济高质量发展的代表。\n\n![](/media/images/668497bf403461999d55ce7212966a0dda88c098b7261acb68c8a97c444ffd3f.jpg)\n\n**（4）打造枞阳地标产品**\n\n有机地标食用菌基地生产的羊肚菌已经打造成为枞阳县的地理标志产品，为当地凸显着区域特色,打造地方、区域品牌积累文化属性。\n\n![](/media/images/e63790cf004ade7ab7f9ef61cf15e87fe7ffb6239fb307eff7e0b600bb442d0d.jpg)\n\n**（5）长三角数字农业优秀案例**\n\n有机地标基地凭借在数字化转型方面的创新能力和实践成果，荣获了2023年智慧长三角数字化转型优秀案例二等奖。\n\n![](/media/images/d7e4334eed5856e6c240e6104','document','528f5b96d0434673b10c97847ff1f238','D:\\my_project\\file pipeline channel\\uploads\\694bb22c5f621b3b9d4addda61f47d8c05d31d9f5d6496cd9b13eddb6ca8c60c.docx','公司','{\"product_id\": \"1\"}','deleted','tenant',1,'0fee6590fa50a53222fee128cf78a5fa150bbc57c1e25b8c503e5fec382aa5ab',1608,NULL,NULL,'2026-08-28 15:15:51.749','pipeline','pipeline','2026-08-28 15:15:51.760','2026-08-29 21:01:47.393'),(299,'Influencer','Influencer_knowlege','18391d321a434ff7a7c3dd3ac61eb56a','**8、公司荣誉**','**8、公司荣誉**\n1. 详见常规手卡\n2. 产品卖点\n\n（1）产品均为有机认证产品，可提供有机认证、绿色认证、检测报告（0添加）；\n\n（2）产品均为基地自产自销，可提供基地拍摄和溯源拍摄；产品自身均自带溯源二维码，可扫码了解种植采收包装等全生命过程；\n\n（3）其中黑木耳和羊肚菌为有机绿色双认证产品，全网唯一具备双认证的产品（可核实查验）；\n\n（4）礼盒装产品均为一级产品精挑细选，品质佳，同等价格下优于市场其他产品品质。普通装产品为二级产品与市场同类有机产品相似，2盒以上有价格优势。\n\n三、知识科普\n\n1、有机产品\n\n（1）什么是“有机产品”?\n\n“有机产品”是指生产、加工、销售过程符合中国有机产品国家标准，获得有机产品认证证书，并加施中国有机产品认证标志的供人类消费、动物食用的产品。\n\n（2）什么是“有机产品认证”?\n\n有机产品认证是指认证机构按照《有机产品》国家标GB19630-2011和《有机产品认证管理办法》以及《有机产品认证实施规则》的规定对有机产品生产和加工过程进行评价的活动。在我国境内销售的有机产品均需经国家认监委批准的认证机构认证。\n\n（3）有机转换期的规定?\n\n根据国家有机产品标准规定，一年生作物的转换期一般不少于 24个月，多年生作物的转换期一般不少于36个月，转换期内必须按照国家有机产品标准的要求进行管理。\n\n（4）有机产品必须同时具备四个条件\n\n1）原料必须来自已经建立或正在建立的有机农业生产体系，或采用有机方式采集的野生天然产品；\n\n2）产品在整个生产过程中必须严格道循有机产品的加工、包装、贮藏、运输等要求；\n\n3）生产者在有机产品的生产和流通过程中，有完善的跟踪审查体系和完整的生产、销售档案记录；\n\n4）必须通过独立的有机产品认证机构认证审查。\n\n（5）有机产品都有啥?\n\n有机食品是有机产品的一类，目前我国有机食品包括谷物、蔬菜、水果、食用菌、茶叶、肉及肉制品、乳制品食用油、酒类、饮料。\n\n（6）有机产品认证流程\n\n1）有机产品生产或加工企业或者其认证委托人或者经营者；\n\n2）认证申请；\n\n3）认证机构进行文件审核、评审合格受理；\n\n4）认证检查员进行生产基地(养殖场)或加工现场或经营场所检查、形成检查报；\n\n5）认证机构作出认证决定；\n\n6）颁发证书；\n\n7）证后跟踪管理。\n\n2、绿色食品\n\n（1）什么是“绿色食品”？\n\n绿色食品是指产自优良生态环境、按照绿色食品标准生产、实行全程质量控制并获得绿色食品标志使用权的安全、优质食用农产品及相关产品。\n\n（2）绿色食品必须同时具备哪些条件？\n\n1）符合《中华人民共和国食品安全法》和《中华人民共和国农产品质量安金法》等法律法规规定；\n\n2）在国家工商总局商标局核定的绿色食品标志商标盖商品范围内；\n\n3）产品或产品廉料产地环境符合绿色食品产地环境质量标准；','**8、公司荣誉**\n1. 详见常规手卡\n2. 产品卖点\n\n（1）产品均为有机认证产品，可提供有机认证、绿色认证、检测报告（0添加）；\n\n（2）产品均为基地自产自销，可提供基地拍摄和溯源拍摄；产品自身均自带溯源二维码，可扫码了解种植采收包装等全生命过程；\n\n（3）其中黑木耳和羊肚菌为有机绿色双认证产品，全网唯一具备双认证的产品（可核实查验）；\n\n（4）礼盒装产品均为一级产品精挑细选，品质佳，同等价格下优于市场其他产品品质。普通装产品为二级产品与市场同类有机产品相似，2盒以上有价格优势。\n\n三、知识科普\n\n1、有机产品\n\n（1）什么是“有机产品”?\n\n“有机产品”是指生产、加工、销售过程符合中国有机产品国家标准，获得有机产品认证证书，并加施中国有机产品认证标志的供人类消费、动物食用的产品。\n\n（2）什么是“有机产品认证”?\n\n有机产品认证是指认证机构按照《有机产品》国家标GB19630-2011和《有机产品认证管理办法》以及《有机产品认证实施规则》的规定对有机产品生产和加工过程进行评价的活动。在我国境内销售的有机产品均需经国家认监委批准的认证机构认证。\n\n（3）有机转换期的规定?\n\n根据国家有机产品标准规定，一年生作物的转换期一般不少于 24个月，多年生作物的转换期一般不少于36个月，转换期内必须按照国家有机产品标准的要求进行管理。\n\n（4）有机产品必须同时具备四个条件\n\n1）原料必须来自已经建立或正在建立的有机农业生产体系，或采用有机方式采集的野生天然产品；\n\n2）产品在整个生产过程中必须严格道循有机产品的加工、包装、贮藏、运输等要求；\n\n3）生产者在有机产品的生产和流通过程中，有完善的跟踪审查体系和完整的生产、销售档案记录；\n\n4）必须通过独立的有机产品认证机构认证审查。\n\n（5）有机产品都有啥?\n\n有机食品是有机产品的一类，目前我国有机食品包括谷物、蔬菜、水果、食用菌、','document','528f5b96d0434673b10c97847ff1f238','D:\\my_project\\file pipeline channel\\uploads\\694bb22c5f621b3b9d4addda61f47d8c05d31d9f5d6496cd9b13eddb6ca8c60c.docx','公司','{\"product_id\": \"1\"}','deleted','tenant',1,'950b74c4f361b29bb97a96efc5893129a8436e96cf2162d28dd03097ed862d3c',1185,NULL,NULL,'2026-08-28 15:15:51.749','pipeline','pipeline','2026-08-28 15:15:51.761','2026-08-29 21:01:47.393'),(300,'Influencer','Influencer_knowlege','64a58b318357457b9dd0725439ec2981','**8、公司荣誉**','**8、公司荣誉**\n4）农药、肥料、饲料、善药等投入品使用符合绿色食品投入品使用准则；\n\n5）产品质量符合绿色食品产品质量标准；\n\n6）包装贮运符合绿色食品包装贮运标准。\n\n（3）绿色食品认证程序\n\n1）申请人:认证申请-(环境调查、现场检查、产品抽样)；\n\n2）定点环境机构监测:出具报告；\n\n3）省绿办(文审)：推荐材料；\n\n4）定点产品监测机构:(抽样检测)一出具报告；\n\n5）中国绿色食品发展中心(认证审核):提交评审评审结论；\n\n6）绿色食品认证评审委员会(认证评审)\n\n（4）绿色产品、有机食品、无公害产品的区别\n\n有机食品：不使用农药、激素、化肥等有害物质，国际公认的最安全的食品；\n\n绿色食品：在无污染的生态环境中种植及全过程标准化生产或加工的农产品无公害食品:使用一些农药，但控制在国家规定的允许范围内；\n\n普通食品：不限制使用农药、化肥、生长调节剂、转基因等。\n\n（5）在市场上如何识别绿色食品？\n\n一看绿标：绿色食品图标是上方的太阳、下方的叶片和中心的蓓蕾，字体白字绿底。除包装标签上的印刷内容外，还贴有统一印制的防伪标签，该标签上的编号应与产品包装标签上的编号一致。\n\n二看防伪：部分绿色食品有防伪标志，在荧光下能显现该产品的标准文号和绿色食品发展中心负责人的签名。\n\n三看官网：登录绿色食品官网进行查询。','**8、公司荣誉**\n4）农药、肥料、饲料、善药等投入品使用符合绿色食品投入品使用准则；\n\n5）产品质量符合绿色食品产品质量标准；\n\n6）包装贮运符合绿色食品包装贮运标准。\n\n（3）绿色食品认证程序\n\n1）申请人:认证申请-(环境调查、现场检查、产品抽样)；\n\n2）定点环境机构监测:出具报告；\n\n3）省绿办(文审)：推荐材料；\n\n4）定点产品监测机构:(抽样检测)一出具报告；\n\n5）中国绿色食品发展中心(认证审核):提交评审评审结论；\n\n6）绿色食品认证评审委员会(认证评审)\n\n（4）绿色产品、有机食品、无公害产品的区别\n\n有机食品：不使用农药、激素、化肥等有害物质，国际公认的最安全的食品；\n\n绿色食品：在无污染的生态环境中种植及全过程标准化生产或加工的农产品无公害食品:使用一些农药，但控制在国家规定的允许范围内；\n\n普通食品：不限制使用农药、化肥、生长调节剂、转基因等。\n\n（5）在市场上如何识别绿色食品？\n\n一看绿标：绿色食品图标是上方的太阳、下方的叶片和中心的蓓蕾，字体白字绿底。除包装标签上的印刷内容外，还贴有统一印制的防伪标签，该标签上的编号应与产品包装标签上的编号一致。\n\n二看防伪：部分绿色食品有防伪标志，在荧光下能显现该产品的标准文号和绿色食品发展中心负责人的签名。\n\n三看官网：登录绿色食品官网进行查询。','document','528f5b96d0434673b10c97847ff1f238','D:\\my_project\\file pipeline channel\\uploads\\694bb22c5f621b3b9d4addda61f47d8c05d31d9f5d6496cd9b13eddb6ca8c60c.docx','公司','{\"product_id\": \"1\"}','deleted','tenant',1,'683b6bd44328433307cb8cdbce487683b75e2ee86b601394cd73a9e5de95ca3b',566,NULL,NULL,'2026-08-28 15:15:51.749','pipeline','pipeline','2026-08-28 15:15:51.762','2026-08-29 21:01:47.393'),(301,'Influencer','Influencer_knowlege','373933655a124a63ae274d4c99453c9e','## 有机地标集团企业简介','## 有机地标集团企业简介\n2024The cross year action plan for organic landmarks.\n\n## C ONTENTS\n![](/media/images/55fb4cb998ce07e3f9cc09557660947e09d6a5b044c31a9cf9e1d11cd7a500d2.jpg)\n\nPART ONE企业介绍\n\n![](/media/images/7d80cb41167ce43221ea36f54688c22808ff50acabb912b7876d602bdc298e08.jpg)  \nPART TWO\n\n设施农业\n\n![](/media/images/f083fc20097a1b3fd8778bf0773951c400aeb23f8886ed197b212501449d98b7.jpg)  \nPART THREE  \n生物科技\n\n![](/media/images/036d806798e828ec043b007ade4cbbbb298dd7738eb3a045431e30cbb94dade4.jpg)  \nPART FOUR\n\n投资运营\n\n## 01 企业介绍 The user can demonstrate on a projector or computer, or print the presentation and make it into a film to be used in a wider field The demonstrate on a projector o r computer, or print the presentation\n','## 有机地标集团企业简介\n2024The cross year action plan for organic landmarks.\n\n## C ONTENTS\n![](/media/images/55fb4cb998ce07e3f9cc09557660947e09d6a5b044c31a9cf9e1d11cd7a500d2.jpg)\n\nPART ONE企业介绍\n\n![](/media/images/7d80cb41167ce43221ea36f54688c22808ff50acabb912b7876d602bdc298e08.jpg)  \nPART TWO\n\n设施农业\n\n![](/media/images/f083fc20097a1b3fd8778bf0773951c400aeb23f8886ed197b212501449d98b7.jpg)  \nPART THREE  \n生物科技\n\n![](/media/images/036d806798e828ec043b007ade4cbbbb298dd7738eb3a045431e30cbb94dade4.jpg)  \nPART FOUR\n\n投资运营\n\n## 01 企业介绍 The user can demonstrate on a projector or computer, or print the presentation and make it into a film to be used in a wider field The demonstrate on a projector o r computer, or print the presentation\n','document','aec61125b035410f864b18e6d39e1201','D:\\my_project\\file pipeline channel\\uploads\\22bd922c227f89a1803240d8582607182c3dc0182deccfd652a4ae2b5aa90a91.pdf','公司','{\"product_id\": \"2\"}','deleted','tenant',1,'9ab4dca23b586663d6dacf703cbd4e0b6fba36245e3b5b55ea3bab3f0f99fdc0',720,NULL,NULL,'2026-08-28 16:27:17.035','pipeline','pipeline','2026-08-28 16:27:17.036','2026-08-29 21:07:23.869'),(302,'Influencer','Influencer_knowlege','ccb6042bcefc4c2f85cad28c3ec8e0fb','## 公司简介','## 公司简介\n有机地标（铜陵）控股集团有限公司坐落于农业大省安徽省铜陵市，是一家从事育繁推一体化农业体系建设，以现代种业、农产品加工业、市场流通业及其他产业等“3+N”产业为重点，集合农业种植、科技研发、物联网及区块链技术服务、销售等服务的大型农业全产业链集团公司。在现代设施农业建设与园区运营管理方面拥有丰富的实践经验，实现了现代智慧农业产业园区全产业链的有效闭合，荣获“安徽省数字农业工厂”“先进单位”、“铜陵市科普示范基地”、铜陵市首个“安徽省节水教育实践基地”等荣誉。\n\n![](/media/images/ceab7fcdef237daaaf809e1163be4c840766181ceae15931d51f3c8e5744544e.jpg)\n\n## 数字农业\n公司积极响应国家的三农政策、与各地政府及大型企业合作，打造数字农业112N计划，建立乡村振兴体系、美丽乡村数字化治理体系、农产品溯源体系。\n\n## 公司使命及愿景\n使命：一粒菌种改变世界\n\n愿景：成为世界级食用菌产业链领导者。\n\n价值观：务实进取、努力奋斗、合作共赢、勇于创新，坚持乡村振兴三农发展为奋斗目标。\n\n## 生态农业\n自成立以来公司先后在山东菏泽、海南乐东、新疆、东北三省等多个地区，开展了现代高效农业的先导试点项目，并利用自有生物技术在土壤改良、病害防治等领域取得显著效果，获得了农业部全国绿色基地示范管理办公室和商务部全国农产品流通企业联合体的高度认可。','## 公司简介\n有机地标（铜陵）控股集团有限公司坐落于农业大省安徽省铜陵市，是一家从事育繁推一体化农业体系建设，以现代种业、农产品加工业、市场流通业及其他产业等“3+N”产业为重点，集合农业种植、科技研发、物联网及区块链技术服务、销售等服务的大型农业全产业链集团公司。在现代设施农业建设与园区运营管理方面拥有丰富的实践经验，实现了现代智慧农业产业园区全产业链的有效闭合，荣获“安徽省数字农业工厂”“先进单位”、“铜陵市科普示范基地”、铜陵市首个“安徽省节水教育实践基地”等荣誉。\n\n![](/media/images/ceab7fcdef237daaaf809e1163be4c840766181ceae15931d51f3c8e5744544e.jpg)\n\n## 数字农业\n公司积极响应国家的三农政策、与各地政府及大型企业合作，打造数字农业112N计划，建立乡村振兴体系、美丽乡村数字化治理体系、农产品溯源体系。\n\n## 公司使命及愿景\n使命：一粒菌种改变世界\n\n愿景：成为世界级食用菌产业链领导者。\n\n价值观：务实进取、努力奋斗、合作共赢、勇于创新，坚持乡村振兴三农发展为奋斗目标。\n\n## 生态农业\n自成立以来公司先后在山东菏泽、海南乐东、新疆、东北三省等多个地区，开展了现代高效农业的先导试点项目，并利用自有生物技术在土壤改良、病害防治等领域取得显著效果，获得了农业部全国绿色基地示范管理办公室和商务部全国农产品流通企业联合体的高度认可。','document','aec61125b035410f864b18e6d39e1201','D:\\my_project\\file pipeline channel\\uploads\\22bd922c227f89a1803240d8582607182c3dc0182deccfd652a4ae2b5aa90a91.pdf','公司','{\"product_id\": \"2\"}','deleted','tenant',1,'58bfb47