s/cb77dced30c1ffb0420cea981816e32014b8e66a068b1f735de818cc7b075da4.jpg\"}], \"product_id\": \"1\"}','active','tenant',1,'0fa7206c4f6851fc7b2a56fc2931e2bef403b08f5e4d80d918cc129f36cf8488',130,NULL,NULL,'2026-08-29 21:06:26.116','pipeline','pipeline','2026-08-29 21:06:26.124','2026-08-29 21:06:26.124'),(345,'Influencer','Influencer_knowlege','2faf7e189b6b47bba012414e3a609db2','## “中华神菇”——茶树菇','# 有机地标农场手册有机地标铜陵集团有限公司\n## “中华神菇”——茶树菇\n茶树菇作为食用菌，食味鲜美，口感脆，香味浓郁、纯正，质地细嫩，还可加工为茶树菇罐头、茶树菇原汁酱油、茶树菇浓缩液和茶树干菇等产品。此外茶树菇营养丰富。茶树菇还具有补益、降压、安心醒脑和抗衰老等功能，对尿频、水肿、气喘、小儿尿床、关节炎、低热和解毒等均有显著的疗效。实验证明，茶树菇提取物对小白鼠肉瘤和艾氏腹水癌的抑制率高达80% \\~ 90%。\n','# 有机地标农场手册有机地标铜陵集团有限公司\n## “中华神菇”——茶树菇\n茶树菇作为食用菌，食味鲜美，口感脆，香味浓郁、纯正，质地细嫩，还可加工为茶树菇罐头、茶树菇原汁酱油、茶树菇浓缩液和茶树干菇等产品。此外茶树菇营养丰富。茶树菇还具有补益、降压、安心醒脑和抗衰老等功能，对尿频、水肿、气喘、小儿尿床、关节炎、低热和解毒等均有显著的疗效。实验证明，茶树菇提取物对小白鼠肉瘤和艾氏腹水癌的抑制率高达80% \\~ 90%。\n','document','3bbadcdb357a4f658691b3425d204a7e','D:\\my_project\\file pipeline channel\\uploads\\cbe2c8bc1eab38570ae0c11c3dcb1a89699826a1cf4445e591d5324ebf0c7e6d.pdf','农场手册','{\"images\": [{\"alt\": \"\", \"ref\": \"/media/images/97444f4657996e17341a3e7cc242c81892e4a06129eeac0382f7174d72926e8a.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/67ddf570878102f54be6de57d081e6ba51177561dee80e8514e5007867a0b6f3.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/39917308c93f2d36518659cde03e221d41c59a53f61fe690d8c8d3d51f138bb1.jpg\"}], \"product_id\": \"1\"}','active','tenant',1,'f477a3c0cdf77392110ba2cda62e4d482240b4bf90e82403e1c64d67bdad9ea5',211,NULL,NULL,'2026-08-29 21:06:26.116','pipeline','pipeline','2026-08-29 21:06:26.125','2026-08-29 21:06:26.125'),(346,'Influencer','Influencer_knowlege','68893b9e314f4f1bb105fa766c06915a','## “荷叶离褶伞”——鹿茸菇','# 有机地标农场手册有机地标铜陵集团有限公司\n## “荷叶离褶伞”——鹿茸菇\n鹿茸菇含有高蛋白质和多种氨基酸，还含维生素B1、B2、C和PP，具有很高的营养价值和特殊的药用效果。经烹调后，脆松适度，味道可口，如配上猪、鸡肉共炒，则食味更加鲜美，胜过鸡、鸭、鱼、肉单作的荤菜。研究表明，鹿茸菇有的β葡聚糖，长期食用有抗肿瘤的功效，同时，鹿茸菇具有对血管紧张素I转换酶的抑制活性与降血压作用，还兼具有降低胆固醇、抗糖尿病、抗过敏等药用作用。\n','# 有机地标农场手册有机地标铜陵集团有限公司\n## “荷叶离褶伞”——鹿茸菇\n鹿茸菇含有高蛋白质和多种氨基酸，还含维生素B1、B2、C和PP，具有很高的营养价值和特殊的药用效果。经烹调后，脆松适度，味道可口，如配上猪、鸡肉共炒，则食味更加鲜美，胜过鸡、鸭、鱼、肉单作的荤菜。研究表明，鹿茸菇有的β葡聚糖，长期食用有抗肿瘤的功效，同时，鹿茸菇具有对血管紧张素I转换酶的抑制活性与降血压作用，还兼具有降低胆固醇、抗糖尿病、抗过敏等药用作用。\n','document','3bbadcdb357a4f658691b3425d204a7e','D:\\my_project\\file pipeline channel\\uploads\\cbe2c8bc1eab38570ae0c11c3dcb1a89699826a1cf4445e591d5324ebf0c7e6d.pdf','农场手册','{\"images\": [{\"alt\": \"\", \"ref\": \"/media/images/9ec4eea7d2941df8416f6bf4a12b688f362a29b30e78fc072946b884afc0866d.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/086d9006016f5a819658d07e052d38f52d1dcd4da421214988017fe8adb48307.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/917acf7faed07b34b52e016d8ae4922c1cc216483f6a9b15526c993bc9d23339.jpg\"}], \"product_id\": \"1\"}','active','tenant',1,'1da4bf6029f1c290a98dc08572e94eaf25a214743aa7a4c68b79c6b9caaf182d',219,NULL,NULL,'2026-08-29 21:06:26.116','pipeline','pipeline','2026-08-29 21:06:26.126','2026-08-29 21:06:26.126'),(347,'Influencer','Influencer_knowlege','9f309e2a9ca74f519a655a8fbd32fe6b','## “菌种皇后”——鸡枞菌','# 有机地标农场手册有机地标铜陵集团有限公司\n## “菌种皇后”——鸡枞菌\n《本草纲目》记载鸡枞菌有“益味、清神、治痔”的作用， [6]具有健脾和胃，疗痔的功效，主治脘腹胀满、消化不良、精神疲乏、痔疮。 [8]鸡枞菌可食用，所含人体所必需的氨基酸、蛋白质、脂肪等，可用来煮汤、烧菜等，其滋味鲜美，风味类似鸡汤。\n','# 有机地标农场手册有机地标铜陵集团有限公司\n## “菌种皇后”——鸡枞菌\n《本草纲目》记载鸡枞菌有“益味、清神、治痔”的作用， [6]具有健脾和胃，疗痔的功效，主治脘腹胀满、消化不良、精神疲乏、痔疮。 [8]鸡枞菌可食用，所含人体所必需的氨基酸、蛋白质、脂肪等，可用来煮汤、烧菜等，其滋味鲜美，风味类似鸡汤。\n','document','3bbadcdb357a4f658691b3425d204a7e','D:\\my_project\\file pipeline channel\\uploads\\cbe2c8bc1eab38570ae0c11c3dcb1a89699826a1cf4445e591d5324ebf0c7e6d.pdf','农场手册','{\"images\": [{\"alt\": \"\", \"ref\": \"/media/images/f0f45c503e56a3f6d270911ff483cbe06188fa535f5d92e39c9fca2b9c4049ce.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/8bc3f7f524bd424f69040e47e4af571f9ef02f25d8b704f1d2ee895595d8827b.jpg\"}], \"product_id\": \"1\"}','active','tenant',1,'f5702f700b9b6412b80f2cad1a13a1e7b7ab9832bfe2597d6703a70ffcb6e9b2',156,NULL,NULL,'2026-08-29 21:06:26.116','pipeline','pipeline','2026-08-29 21:06:26.127','2026-08-29 21:06:26.127'),(348,'Influencer','Influencer_knowlege','8de77c3fdd994912