ect\\file pipeline channel\\uploads\\22bd922c227f89a1803240d8582607182c3dc0182deccfd652a4ae2b5aa90a91.pdf','公司','{\"images\": [{\"alt\": \"\", \"ref\": \"/media/images/32b79e1d753282e976efee0b49cf50302a5d21c89d4a12fe94e6e6766a8e68c6.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/ad5816b34fbaea1a7d8dbf5512b41f1c84545fb5eacc834b0003a2538c6a24ca.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/a13eeba38d880b90798ca063e889af606491a53d3303f6837335c802ab6b8a53.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/ab801644c8c511bf59ba1c7b2f57554ac2b6477ff23cc1c93d146439e033b7a9.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/6db55476c7ed64bc2273d774e1b07c690cd62c46e26792e95ef6ea263f10865e.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/5f50276e6a28270d640e86c98a3fd27fa09d6b42a45da86faed032436695d623.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/7ab6d7664def52650cf518370028fe485788cf264bcfb453545e649447fa77f6.jpg\"}, {\"alt\": \"\", \"ref\": \"/media/images/0ccc61adab0ad0157f646d538879dc5b9cee7542c930f548535d11d8802a5299.jpg\"}], \"product_id\": \"2\"}','active','tenant',1,'3d15358f91b1e54959f3f2f382f1ad2394693ae1d52b5f0cf2427608d0b67971',244,NULL,NULL,'2026-08-29 21:07:04.664','pipeline','pipeline','2026-08-29 21:07:04.753','2026-08-29 21:07:04.753'),(385,'Influencer','Influencer_knowlege','1d5c238edebd47acb0aa8d58b71754f2','## 以调整农业产业结构、增加农民收入为宗旨','# 打造工厂化食用菌产业园区为目标\n## 以调整农业产业结构、增加农民收入为宗旨\n\n符合国家及枞阳县农业产业政策和产业布局，市场前景好，建设规模和内容切合实际，运行模式科学合理，经济、社会和生态效益显著。项目建设对于提高项目单位经济效益、促进枞阳县特色农业产业发展以及精准扶贫具有重要意义，该项目的建设十分必要。','# 打造工厂化食用菌产业园区为目标\n## 以调整农业产业结构、增加农民收入为宗旨\n\n符合国家及枞阳县农业产业政策和产业布局，市场前景好，建设规模和内容切合实际，运行模式科学合理，经济、社会和生态效益显著。项目建设对于提高项目单位经济效益、促进枞阳县特色农业产业发展以及精准扶贫具有重要意义，该项目的建设十分必要。','document','aec61125b035410f864b18e6d39e1201','D:\\my_project\\file pipeline channel\\uploads\\22bd922c227f89a1803240d8582607182c3dc0182deccfd652a4ae2b5aa90a91.pdf','公司','{\"images\": [{\"alt\": \"\", \"ref\": \"/media/images/d6a14ada8eeb42d90c643d62681c0df9cbbaa38ecd29276c81d01cb716a89d12.jpg\"}], \"product_